mapper.select:
select a.*, (SELECT GROUP_CONCAT(CONCAT(t.tagId, ':', t.tagName, ':', IFNULL(t.tagColor, '#409EFF')) SEPARATOR '|') FROM userfile_tag ut INNER JOIN tag t ON ut.tagId = t.tagId WHERE ut.userFileId = a.userFileId) as tagList from userfile a left join image on a.fileId = image.fileId left join file on file.fileId = a.fileId
extendName in (select fileExtendName from fileclassification where fileTypeId = #{fileTypeId})
extendName not in (select fileExtendName from fileclassification where fileTypeId in (1, 2, 3, 4))
and a.isDir = 0
and a.userId = #{userFile.userId}
and a.filePath = #{userFile.filePath}
and a.extendName = #{userFile.extendName}
and a.userFileId = #{userFile.userFileId}
and a.fileName = #{userFile.fileName}
and a.deleteFlag = 0
ORDER BY isDir desc, uploadTime desc

select a.*, (SELECT GROUP_CONCAT(CONCAT(t.tagId, ':', t.tagName, ':', IFNULL(t.tagColor, '#409EFF')) SEPARATOR '|') FROM userfile_tag ut2 INNER JOIN tag t ON ut2.tagId = t.tagId WHERE ut2.userFileId = a.userFileId) as tagList from userfile a left join image on a.fileId = image.fileId left join file on file.fileId = a.fileId inner join userfile_tag ut on a.userFileId = ut.userFileId
ut.tagId = #{tagId}
and a.userId = #{userFile.userId}
and a.deleteFlag = 0
ORDER BY a.isDir desc

SELECT SUM(fileSize) FROM userfile
LEFT JOIN file ON file.fileId = userfile.fileId
WHERE userfile.userId = #{userId}
